// Read-only public GitHub metadata for PR #2 Foundation run 39359423680, attempts 1 and 2. No log or artifact download.
const root = 'https://api.github.com/repos/chroniicallydiistracted/lorcana-online-tcg/actions/runs/';
async function get(path) {
  const r = await fetch(root + path, { headers: { Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' }, signal: AbortSignal.timeout(15000) });
  if (!r.ok) throw new Error('Public GitHub metadata unavailable: ' + r.status);
  return r.json();
}
const out = [];
for (const attempt of [1, 2]) {
  const v = await get('39359423680/attempts/' + attempt), j = await get('39359423680/attempts/' + attempt + '/jobs?per_page=100');
  if (v.id !== 39359423680 || v.run_attempt !== attempt || v.head_sha !== '3f134ade9fc0a4a29621e7385a044fc969d56e8e') throw new Error('Unexpected hosted metadata');
  out.push({ id: v.id, attempt, event: v.event, head_branch: v.head_branch, head_sha: v.head_sha, status: v.status, conclusion: v.conclusion, run_started_at: v.run_started_at, updated_at: v.updated_at,
    jobs: j.jobs.map(x => ({ name: x.name, conclusion: x.conclusion, started_at: x.started_at, completed_at: x.completed_at, failed_steps: x.steps.filter(s => s.conclusion === 'failure').map(s => s.name) })) });
}
if (out.some(o => o.conclusion !== 'failure')) throw new Error('Hosted results differ from the reviewer observation');
console.log(JSON.stringify(out));
